from typing import List

class Solution:
    def minSubArrayLen(self, target: int, nums: List[int]) -> int:
        best = float("inf")
        for left in range(len(nums)):
            total = 0
            for right in range(left, len(nums)):
                total += nums[right]
                if total >= target:
                    best = min(best, right - left + 1)
                    break
        return 0 if best == float("inf") else best

